const raw = $json;
const body = raw.body && typeof raw.body === 'object' && !Array.isArray(raw.body)
  ? raw.body
  : raw;

const now = new Date();
const suffix = Math.random().toString(36).slice(2, 10).toUpperCase();
const requestId = `AGENT-${now.getTime()}-${suffix}`;
const correlationId = `CORR-${now.getTime()}-${suffix}`;

const errors = [];
const clarifications = [];

const principalKey = typeof body.principal_key === 'string'
  ? body.principal_key.trim()
  : '';

if (!principalKey || principalKey.length > 128) {
  errors.push({
    code: 'PRINCIPAL_KEY_REQUIRED',
    message: 'A valid principal_key is required.'
  });
}

const allowedKpis = new Set([
  'closed_won_revenue',
  'open_pipeline',
  'closed_won_deals',
  'win_rate'
]);

const allowedPeriods = new Set([
  'today','yesterday',
  'this_week','last_week',
  'this_month','last_month',
  'this_quarter','last_quarter',
  'this_year','last_year'
]);

const allowedModes = new Set([
  'metric_report',
  'trend_report',
  'comparison_report'
]);

const allowedFilterFields = new Set([
  'sales_rep',
  'lead_source',
  'deal_stage'
]);

function normalizeFilters(input) {
  if (input === undefined || input === null) return {};
  if (typeof input !== 'object' || Array.isArray(input)) {
    errors.push({code:'FILTERS_INVALID', message:'filters must be an object.'});
    return {};
  }

  const output = {};
  for (const [field, rawValue] of Object.entries(input)) {
    if (!allowedFilterFields.has(field)) {
      errors.push({
        code:'FILTER_FIELD_NOT_SUPPORTED',
        message:`Unsupported filter field: ${field}`
      });
      continue;
    }

    const values = Array.isArray(rawValue) ? rawValue : [rawValue];
    if (
      values.length === 0 ||
      values.length > 50 ||
      values.some(v => typeof v !== 'string' || !v.trim() || v.trim().length > 200)
    ) {
      errors.push({
        code:'FILTER_VALUE_INVALID',
        message:`Invalid filter value for ${field}.`
      });
      continue;
    }

    output[field] = [...new Set(values.map(v => v.trim()))];
  }
  return output;
}

let intent = null;
let interpreterType = null;

if (
  body.structured_intent &&
  typeof body.structured_intent === 'object' &&
  !Array.isArray(body.structured_intent)
) {
  interpreterType = 'structured_intent_v1';
  const supplied = body.structured_intent;

  const kpiKey = typeof supplied.kpi_key === 'string' ? supplied.kpi_key.trim() : '';
  const periodKey = typeof supplied.period_key === 'string' ? supplied.period_key.trim() : '';
  const mode = typeof supplied.mode === 'string' ? supplied.mode.trim() : 'metric_report';
  const dimensions = Array.isArray(supplied.dimensions) ? supplied.dimensions : [];

  if (!allowedKpis.has(kpiKey)) {
    clarifications.push({
      code:'KPI_CLARIFICATION_REQUIRED',
      question:'Which supported KPI do you want: closed won revenue, open pipeline, closed won deals, or win rate?'
    });
  }

  if (!allowedPeriods.has(periodKey)) {
    clarifications.push({
      code:'PERIOD_CLARIFICATION_REQUIRED',
      question:'Which reporting period should I use (for example this month, last month, this quarter, or last quarter)?'
    });
  }

  if (!allowedModes.has(mode)) {
    clarifications.push({
      code:'REPORT_MODE_CLARIFICATION_REQUIRED',
      question:'Should this be a metric report, trend report, or comparison report?'
    });
  }

  if (dimensions.length > 0) {
    clarifications.push({
      code:'BREAKDOWN_NOT_ENABLED',
      question:'This agent core currently returns governed scalar metrics. Please remove the breakdown dimension for this request.'
    });
  }

  intent = {
    kpi_key: kpiKey,
    period_key: periodKey,
    mode,
    filters: normalizeFilters(supplied.filters),
  };
} else {
  interpreterType = 'deterministic_nl_v1';
  const question = typeof body.question === 'string' ? body.question.trim() : '';

  if (!question || question.length > 1000) {
    errors.push({
      code:'QUESTION_REQUIRED',
      message:'A report question of at most 1000 characters is required.'
    });
  }

  const q = question.toLowerCase().replace(/\s+/g, ' ');

  if (/\bby\s+(sales\s+rep|rep|lead\s+source|stage)\b/.test(q)) {
    clarifications.push({
      code:'BREAKDOWN_NOT_ENABLED',
      question:'This agent core currently returns governed scalar metrics. Please ask for the headline KPI without a breakdown.'
    });
  }

  const metricMatches = [];
  if (/\b(closed[\s-]*won revenue|won revenue|revenue won)\b/.test(q)) {
    metricMatches.push('closed_won_revenue');
  }
  if (/\b(open pipeline|pipeline value)\b/.test(q) || /\bpipeline\b/.test(q)) {
    metricMatches.push('open_pipeline');
  }
  if (/\b(closed[\s-]*won deals?|won deals?|deals? won)\b/.test(q)) {
    metricMatches.push('closed_won_deals');
  }
  if (/\bwin rate\b/.test(q)) {
    metricMatches.push('win_rate');
  }

  const uniqueMetrics = [...new Set(metricMatches)];
  if (uniqueMetrics.length !== 1) {
    clarifications.push({
      code:'KPI_CLARIFICATION_REQUIRED',
      question:'Which supported KPI do you want: closed won revenue, open pipeline, closed won deals, or win rate?'
    });
  }

  const periodPatterns = [
    ['last_quarter', /\blast quarter\b/],
    ['this_quarter', /\bthis quarter\b/],
    ['last_month', /\blast month\b/],
    ['this_month', /\bthis month\b/],
    ['last_week', /\blast week\b/],
    ['this_week', /\bthis week\b/],
    ['last_year', /\blast year\b/],
    ['this_year', /\bthis year\b/],
    ['yesterday', /\byesterday\b/],
    ['today', /\btoday\b/],
  ];

  const periodMatches = periodPatterns
    .filter(([,pattern]) => pattern.test(q))
    .map(([key]) => key);

  if (periodMatches.length !== 1) {
    clarifications.push({
      code:'PERIOD_CLARIFICATION_REQUIRED',
      question:'Which reporting period should I use (for example this month, last month, this quarter, or last quarter)?'
    });
  }

  let mode = 'metric_report';
  if (/\b(compare|comparison|compared|versus|vs\.?)\b/.test(q)) {
    mode = 'comparison_report';
  } else if (/\b(trend|change|changing|movement|moving)\b/.test(q)) {
    mode = 'trend_report';
  }

  intent = {
    kpi_key: uniqueMetrics.length === 1 ? uniqueMetrics[0] : null,
    period_key: periodMatches.length === 1 ? periodMatches[0] : null,
    mode,
    filters: {},
  };
}

return {
  request_id: requestId,
  correlation_id: correlationId,
  principal_key: principalKey,
  question: typeof body.question === 'string' ? body.question.trim() : null,
  interpreter_type: interpreterType,
  structured_intent: intent,
  validation: {
    is_valid: errors.length === 0,
    errors,
    clarification_required: clarifications.length > 0,
    clarifications,
    validated_at: now.toISOString(),
  },
  should_execute: errors.length === 0 && clarifications.length === 0,
  workflow_stage: errors.length === 0 && clarifications.length === 0
    ? 'agent_intent_ready'
    : 'agent_clarification_required',
};

const ctx = $('CTX | Interpret Report Request').item.json;
let result = $json.agent_result;

if (typeof result === 'string') {
  try { result = JSON.parse(result); } catch { result = null; }
}

if (!result || result.status !== 'approved') {
  const internalReason = result?.reason ?? 'REPORT_NOT_AUTHORIZED';
  const circuitOpen = internalReason === 'CIRCUIT_OPEN';
  return {
    request_id: ctx.request_id,
    correlation_id: ctx.correlation_id,
    http_status: circuitOpen ? 503 : 403,
    response_body: {
      status: 'rejected',
      request_id: ctx.request_id,
      correlation_id: ctx.correlation_id,
      error: {
        code: circuitOpen ? 'SERVICE_TEMPORARILY_UNAVAILABLE' : 'REPORT_NOT_AUTHORIZED',
        message: circuitOpen
          ? 'The reporting service is temporarily unavailable. Please retry after the circuit recovery window.'
          : 'The requested report could not be authorized for execution.',
        retry_after: circuitOpen ? (result?.retry_after ?? null) : undefined
      }
    },
    audit_event: {
      event_type: 'report_rejected',
      stage: 'agent_core',
      actor: 'n8n_agent_core',
      payload: {
        principal_key: ctx.principal_key,
        kpi_key: ctx.structured_intent?.kpi_key ?? null,
        period_key: ctx.structured_intent?.period_key ?? null,
        mode: ctx.structured_intent?.mode ?? null,
        reason: internalReason,
        interpreter_type: ctx.interpreter_type
      }
    }
  };
}

return {
  request_id: ctx.request_id,
  correlation_id: ctx.correlation_id,
  http_status: 200,
  response_body: {
    status: 'success',
    request_id: ctx.request_id,
    correlation_id: ctx.correlation_id,
    report: {
      kpi_key: result.kpi_key,
      mode: result.mode,
      unit: result.unit,
      currency_code: result.currency_code,
      reporting_timezone: result.reporting_timezone,
      current_period: result.current_period,
      previous_period: result.previous_period,
      analysis: result.analysis
    }
  },
  audit_event: {
    event_type: 'report_completed',
    stage: 'agent_core',
    actor: 'n8n_agent_core',
    payload: {
      principal_key: ctx.principal_key,
      kpi_key: result.kpi_key,
      period_key: ctx.structured_intent?.period_key ?? null,
      mode: result.mode,
      data_scope: result.data_scope,
      interpreter_type: ctx.interpreter_type,
      status: 'approved'
    }
  }
};

const ctx = $json;
const clarification = Array.isArray(ctx.validation?.clarifications)
  ? ctx.validation.clarifications
  : [];
const validationErrors = Array.isArray(ctx.validation?.errors)
  ? ctx.validation.errors
  : [];

const questions = clarification.map(item => ({
  code: item.code,
  question: item.question
}));

if (questions.length === 0 && validationErrors.length > 0) {
  questions.push({
    code: 'REQUEST_CLARIFICATION_REQUIRED',
    question: 'Please provide a valid principal and a supported report question.'
  });
}

return {
  request_id: ctx.request_id,
  correlation_id: ctx.correlation_id,
  http_status: 422,
  response_body: {
    status: 'clarification_required',
    request_id: ctx.request_id,
    correlation_id: ctx.correlation_id,
    questions
  },
  audit_event: {
    event_type: 'report_clarification_required',
    stage: 'agent_core',
    actor: 'n8n_agent_core',
    payload: {
      principal_key: ctx.principal_key || null,
      interpreter_type: ctx.interpreter_type,
      clarification_codes: questions.map(q => q.code),
      validation_error_codes: validationErrors.map(e => e.code)
    }
  }
};
